def rand_tree(rng, n, kind, lo, hi):
    if n == 0:
        return 'null'
    val = [rng.randint(lo, hi) for _ in range(n)]
    L = [-1] * n
    R = [-1] * n
    if kind == 'random':
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            k = rng.randrange(len(slots))
            slots[k], slots[-1] = slots[-1], slots[k]
            p, s = slots.pop()
            if s == 0:
                L[p] = i
            else:
                R[p] = i
            slots.append((i, 0))
            slots.append((i, 1))
    elif kind == 'chain':
        for i in range(1, n):
            if rng.random() < 0.5:
                L[i - 1] = i
            else:
                R[i - 1] = i
    elif kind == 'left':
        for i in range(1, n):
            L[i - 1] = i
    elif kind == 'right':
        for i in range(1, n):
            R[i - 1] = i
    else:
        for i in range(1, n):
            p = (i - 1) // 2
            if i % 2 == 1:
                L[p] = i
            else:
                R[p] = i
    out = []
    q = [0]
    h = 0
    while h < len(q):
        x = q[h]
        h += 1
        if x < 0:
            out.append('null')
            continue
        out.append(str(val[x]))
        q.append(L[x])
        q.append(R[x])
    while out[-1] == 'null':
        out.pop()
    return ' '.join(out)

def gen(rng):
    tests = ['null', '5', '0', '10 4 6 null 3 2', '1 2', '1 null 2', '3 2 1 5 null null 4']
    kinds = ['random', 'chain', 'left', 'right', 'full']
    for _ in range(30):
        tests.append(rand_tree(rng, rng.randint(1, 14), rng.choice(kinds), -9, 9))
    tests.append(rand_tree(rng, 10000, 'random', -1000, 1000))
    tests.append(rand_tree(rng, 5000, 'left', -1000, 1000))
    tests.append(rand_tree(rng, 5000, 'chain', -1000, 1000))
    tests.append(rand_tree(rng, 10000, 'full', -1000, 1000))
    return tests

